/**
 * SLICE-236-7 (D-235-9): REAL emitted events of the dogfood 3-hop chain
 * as adapter conformance fixtures — not synthetic payloads.
 *
 * tests/process/fixtures/dogfood/events.json is generated by
 * scripts/dump-process-fixtures-236-7.mts through the production
 * emitters (makeChain → shipment.ts emit + venueJobToEconomic for the
 * job twin). manifest.json pins a per-event canonical digest —
 * round-trip: projection.sourceEvent → fixture event → recompute
 * JCS+SHA-256 == manifest (mapping-readiness criterion 6, R2-10).
 *
 * Status table (documented, deterministic — AC1):
 *   supply_chain/handoff,verify + venue/deliver,verify(+dh) → SUPPORTED
 *   venue/verify hop1 — no shipmentId/deliverableHash in the real emit
 *     → PARTIAL + ASSET_REF_MISSING (the honest shape of that hop's job)
 *   supply_chain work_offer/work_accept/pay → UNSUPPORTED+TYPE_UNKNOWN
 *     (claimed by the adapter, no step mapping yet)
 *   venue/pay → UNSUPPORTED unmapped (no adapter claims venue pay)
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { createActorResolver } from "../../src/server/lib/process/resolver/actor-resolver";
import type { ActorIdentityRow } from "../../src/server/lib/process/resolver/types";
import { createAdapterRegistry } from "../../src/server/lib/process/adapters";
import { createSupplyChainAdapter } from "../../src/server/lib/process/adapters/supply-chain";
import type { EconomicEventLike } from "../../src/server/lib/process/adapters/types";
import { canonicalDigest, DIGEST_ALGORITHM } from "./fixtures/dogfood/digest";

const CHAIN = 1874;
const ORG = `0x${"aa".repeat(20)}`;
const AGENT = `0x${"bb".repeat(20)}`;
const DEVICE = `0x${"cc".repeat(20)}`;
const KNOWN_ADDRESSES = new Set([ORG, AGENT, DEVICE]);

const DIR = `${import.meta.dirname}/fixtures/dogfood`;
const events = JSON.parse(
  readFileSync(`${DIR}/events.json`, "utf8"),
) as (EconomicEventLike & {
  id: string;
  spec: string;
  idempotencyKey: string;
})[];
const manifest = JSON.parse(
  readFileSync(`${DIR}/manifest.json`, "utf8"),
) as {
  algorithm: string;
  shipmentId: string;
  events: {
    idempotencyKey: string;
    source: string;
    kind: string;
    seq: number;
    sha256: string;
  }[];
};

const registry = createAdapterRegistry([
  createSupplyChainAdapter({
    resolver: createActorResolver({
      actors: {
        getById: async (w) =>
          (new Map<string, ActorIdentityRow>(
            [ORG, AGENT, DEVICE].map((a) => [
              a,
              { type: "EXTERNAL_AGENT" },
            ]),
          )).get(w) ?? null,
      },
      erc8004: { get: async () => undefined, list: async () => [] },
      defaultChainId: CHAIN,
    }),
    chainId: CHAIN,
  }),
]);

describe("dogfood fixtures — manifest integrity (SLICE-236-7)", () => {
  it("every fixture event's recomputed canonical digest matches the manifest", () => {
    expect(manifest.algorithm).toBe(DIGEST_ALGORITHM);
    expect(events.length).toBe(manifest.events.length);
    const byKey = new Map(manifest.events.map((m) => [m.idempotencyKey, m]));
    for (const e of events) {
      const m = byKey.get(e.idempotencyKey);
      expect(m, `manifest missing ${e.idempotencyKey}`).toBeDefined();
      expect(canonicalDigest(e), e.idempotencyKey).toBe(m!.sha256);
    }
  });

  it("fixtures carry no secrets — every address is a known DRY vector", () => {
    const seen: string[] = [];
    const walk = (v: unknown): void => {
      if (typeof v === "string") seen.push(v);
      else if (Array.isArray(v)) v.forEach(walk);
      else if (v && typeof v === "object") {
        Object.values(v).forEach(walk);
      }
    };
    walk(events);
    for (const s of seen) {
      expect(s).not.toMatch(/private.?key|secret|password|BEGIN [A-Z ]*PRIVATE/i);
      if (/^0x[0-9a-fA-F]{40}$/.test(s)) {
        expect(KNOWN_ADDRESSES.has(s.toLowerCase()), `unknown address ${s}`).toBe(
          true,
        );
      }
    }
  });
});

describe("dogfood fixtures — adapter conformance", () => {
  const statusOf = (e: EconomicEventLike): string => {
    if (e.kind === "handoff" || e.kind === "deliver") return "SUPPORTED";
    if (e.kind === "verify") {
      // hop1's real venue verify carries no deliverableHash (that hop
      // proves via proofOfDelivery) → documented PARTIAL.
      return e.sourceId.endsWith("-1") && e.source === "venue"
        ? "PARTIAL"
        : "SUPPORTED";
    }
    return "UNSUPPORTED";
  };

  it("every event projects to its documented status", async () => {
    expect(events.length).toBe(21);
    for (const e of events) {
      const p = await registry.project(e);
      expect(p.mapping.status, `${e.source}/${e.kind} seq=${e.seq}`).toBe(
        statusOf(e),
      );
    }
  });

  it("each projection's sourceEvent points back at the real ledger event", async () => {
    for (const e of events) {
      const p = await registry.project(e);
      expect(p.sourceEvent.id).toBe(e.idempotencyKey);
      expect(p.sourceEvent.source).toBe(e.source);
      expect(p.sourceEvent.sourceId).toBe(e.sourceId);
      expect(p.sourceEvent.seq).toBe(e.seq);
      expect(p.sourceEvent.spec).toBe("econ-events/1");
    }
  });

  it("handoff + deliver + verify projections carry domain interpretation", async () => {
    const byKind = (kind: string, source?: string) =>
      events.filter(
        (e) => e.kind === kind && (source === undefined || e.source === source),
      );
    for (const e of byKind("handoff")) {
      const p = await registry.project(e);
      expect(p.interpretation.stepType).toBe("supply-chain.handoff");
      expect(p.interpretation.subjectRefs[0]?.assetType).toBe(
        "physical.batch",
      );
      expect(p.mapping.issues).toEqual([]);
    }
    for (const e of byKind("deliver")) {
      const p = await registry.project(e);
      expect(p.interpretation.stepType).toBe("supply-chain.deliver");
      const subject = p.interpretation.subjectRefs[0];
      expect(subject?.assetType).toBe("digital.artifact");
      expect(subject?.contentDigest?.algorithm).toBe("keccak256");
    }
    for (const e of byKind("verify", "supply_chain")) {
      const p = await registry.project(e);
      expect(p.interpretation.stepType).toBe("supply-chain.verify");
      expect(p.mapping.issues).toEqual([]);
      // dogfood emits pass verdicts WITHOUT policyRef — criteriaDigest
      // alone never lifts to commitmentPotential (projection ≠ verification).
      expect(p.interpretation.domainData?.commitmentPotential).toBeUndefined();
    }
    // The documented PARTIAL — hop1's venue twin verify.
    const partial = await registry.project(
      events.find((e) => e.source === "venue" && e.sourceId.endsWith("-1") && e.kind === "verify")!,
    );
    expect(partial.mapping.status).toBe("PARTIAL");
    expect(partial.mapping.issues[0]?.code).toBe("ASSET_REF_MISSING");
  });

  it("unmapped kinds project valid UNSUPPORTED rows (both flavors)", async () => {
    for (const e of events.filter(
      (e) => !["handoff", "deliver", "verify"].includes(e.kind),
    )) {
      const p = await registry.project(e);
      expect(p.mapping.status).toBe("UNSUPPORTED");
      expect(p.mapping.issues[0]?.code).toBe("TYPE_UNKNOWN");
      // claimed-but-unmapped kinds name the adapter; venue/pay is
      // claimed by nobody → the registry's unmapped fallback.
      if (e.source === "supply_chain") {
        expect(p.mapping.adapter).toBe("supply-chain");
      } else {
        expect(p.mapping.adapter).toBe("unmapped");
      }
    }
  });
});
